"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["10264"],{22977(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.remanejamento_cruzado_indevido","status":422,"titulo":"Par/fallback de remanejamento s\xf3 se aplicam \xe0 regra CRUZADO"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.remanejamento_cruzado_indevido","requisitos":[],"oQueAconteceu":["No documento publicado, uma modalidade selecionada declarou `remanejamentoPar`, `remanejamentoDestinoFinal`,\\nou os dois, sem ter `regraRemanejamento: CRUZADO`. Este \xe9 o par sim\xe9trico de\\n[`remanejamento_cruzado_incompleto`](/erros/uniplus.selecao.modalidade_selecionada.remanejamento_cruzado_incompleto):\\na mesma coer\xeancia, olhada do lado oposto \u2014 l\xe1, o par faltando quando devia\\nestar presente; aqui, par ou destino final presentes quando deviam faltar. Basta\\num dos dois campos estar preenchido fora da regra `CRUZADO` para causar esta recusa quando os par\xe2metros forem conferidos,\\ninclusive o destino final, que dentro do `CRUZADO` \xe9 opcional.","Esta recusa sai junto com as demais recusas da modalidade; corrija todas antes de selecionar de novo.","**Os campos do documento publicado `regraRemanejamento`, `remanejamentoPar` e\\n`remanejamentoDestinoFinal` n\xe3o v\xeam\\ndo corpo do pedido da defini\xe7\xe3o de distribui\xe7\xe3o de vagas** \u2014 s\xe3o copiados do\\ncadastro de modalidades de Configura\xe7\xe3o, no momento em que a modalidade \xe9\\nselecionada. No cadastro, esses campos s\xe3o `remanejamento.regra`,\\n`remanejamento.par` e `remanejamento.fallback`. O pr\xf3prio cadastro j\xe1 impede esta\\nincoer\xeancia na escrita, tanto na cria\xe7\xe3o quanto na atualiza\xe7\xe3o; pela\\ndefini\xe7\xe3o de distribui\xe7\xe3o de vagas, este c\xf3digo s\xf3 aparece se a modalidade\\nestiver gravada no cadastro de um jeito que contorna essa valida\xe7\xe3o.","Este c\xf3digo tamb\xe9m aparece na **retifica\xe7\xe3o em ato \xfanico**: antes de\\ncongelar a vers\xe3o nova, o sistema l\xea as vers\xf5es j\xe1 publicadas do processo,\\ne essa leitura recria cada modalidade selecionada a partir do que foi\\ncongelado \u2014 a mesma cria\xe7\xe3o \xe9 conferida de novo.","Enquanto houver a recusa de [cota reservada fora da ordem legal](/erros/uniplus.selecao.modalidade_selecionada.cota_reservada_exige_cascata), os par\xe2metros do remanejamento n\xe3o s\xe3o conferidos. Corrija primeiro a cota para que essa confer\xeancia aconte\xe7a."],"comoResolver":["Os campos em excesso n\xe3o est\xe3o no corpo do pedido que voc\xea enviou \u2014 est\xe3o na\\nmodalidade cadastrada em Configura\xe7\xe3o. Corrija l\xe1 a regra de remanejamento\\nou remova o par ou destino final indevido, ou investigue como a modalidade foi\\ngravada sem essa coer\xeancia.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o problema tamb\xe9m n\xe3o est\xe1\\nno que foi enviado agora \u2014 est\xe1 em uma vers\xe3o j\xe1 publicada, que reflete\\numa modalidade j\xe1 incoerente no momento em que foi selecionada."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);